import type { ImageMetadata } from 'astro'
import calibration from '../assets/figures/calibration.png'
import fidelity from '../assets/figures/fidelity.png'
import framework from '../assets/figures/framework.png'
import models from '../assets/figures/models.png'
import type { PdfPage } from './paper'

// The paper's figures. Sources are regenerated by scripts/build-figures.mjs;
// alt text and captions are written per language in src/content/.

export const figureIds = ['framework', 'models', 'calibration', 'fidelity'] as const
export type FigureId = (typeof figureIds)[number]

/**
 * `wide` figures use the full page width on desktop (Figure 1 spans both
 * columns in the paper); `column` figures stay within the reading column.
 */
export type FigureLayout = 'wide' | 'column'

export interface Figure {
  readonly image: ImageMetadata
  readonly page: PdfPage
  readonly layout: FigureLayout
}

export const figures = {
  framework: { image: framework, page: 2, layout: 'wide' },
  models: { image: models, page: 5, layout: 'column' },
  calibration: { image: calibration, page: 6, layout: 'column' },
  fidelity: { image: fidelity, page: 7, layout: 'column' },
} as const satisfies Readonly<Record<FigureId, Figure>>
